use chrono::NaiveDate;
use serde::Serialize;
use serde_json::json;
use std::path::PathBuf;

mod dedup;
mod fetch;
mod output;
mod pdf;
mod state;

use dedup::deduplicate;
use fetch::{fetch_classes, fetch_window};
use output::{write_csv, write_jsonl, write_residuos_csv};
use pdf::download_pdfs;
